+const answers = {
+  q1: ["javascript", "python", "csharp"],
+  q2: ["go", "rust", "java"],
+  q3: ["javascript", "ruby", "php"],
+};
+
+const form = document.getElementById("quiz-form");
+const result = document.getElementById("quiz-result");
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  let correctCount = 0;
+  const questionTotal = Object.keys(answers).length;
+
+  for (const [question, expectedAnswers] of Object.entries(answers)) {
+    const selected = [...form.querySelectorAll(`input[name="${question}"]:checked`)].map(
