+
+    const isCorrect =
+      selected.length === expectedAnswers.length &&
+      expectedAnswers.every((value) => selected.includes(value));
+
+    if (isCorrect) {
+      correctCount += 1;
+    }
+  }
+
+  result.textContent = `You got ${correctCount} of ${questionTotal} questions correct.`;
+});
